const j=$json;
const p=j.payload ?? {};
const text=(p.message?.text ?? p.text ?? '').trim().toLowerCase();
const callback=p.callback_query?.data ?? p.callback_data ?? '';
const state=j.context?.state ?? 'new';
let route='unknown'; let reason='fallback';
if(text==='/start'){route='auth';reason='command:/start';}
else if(text==='/help'){route='support';reason='command:/help';}
else if(text==='/payment'||text==='/pay'){route='payment';reason='payment command';}
else if(text==='/status'){route='order_status';reason='status command';}
else if(callback.startsWith('pay:')){route='payment';reason='payment callback';}
else if(callback.startsWith('approve:')){route='approval';reason='approval callback';}
else if(callback.startsWith('order:')){route='order';reason='order callback';}
else if(state==='awaiting_payment'){route='payment';reason='context';}
else if(state==='awaiting_approval'){route='approval';reason='context';}
else if(state==='awaiting_input'){route='context_input';reason='context';}
else if(/оплат|payment|счет|счёт/.test(text)){route='payment_support';reason='deterministic text rule';}
else if(/заказ|заявк|order/.test(text)){route='order';reason='deterministic text rule';}
else if(/ошиб|не работает|проблем|support|помощ/.test(text)){route='support';reason='deterministic text rule';}
else if(text){route='ai_classification';reason='free text requires classifier';}
return [{json:{...j,routing:{route,reason,llm_required:route==='ai_classification'}}}];
